// Template-level decorative asset for Moody Paper — this time the torn
// edge itself IS the photographed texture (a real torn sheet of paper,
// user-supplied: paper.png), not a code-drawn clip-path shape. Earlier
// version drew the tear with CSS clip-path and only used a photo for the
// flat grain fill — per feedback that read as "not really torn paper, just
// a css cutout" and didn't match the reference board. Two horizontal bands
// were cropped from the same source photo (one around its top tear, one
// around its bottom tear); each is rendered at its own natural aspect
// ratio (width:100%, height:auto — never squashed) so the fiber detail
// stays sharp at any screen width, full-bleed across the whole block per
// feedback ("по всей ширине блока, а не квадратами"), with a flat-color
// middle section (sampled from the same paper) in between.
export const MOODY_PAPER_DECOR = {
  tornTop:
    "data:image/png;base64,",
  tornBottom:
    "data:image/png;base64,",
} as const;
